INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (1,1,1,'브라우저에 URL을 입력하면 URL을 해석하고 도메인을 IP로 변환하기 위해 DNS 조회를 수행합니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (2,1,2,'프로세스는 실행 중인 프로그램의 인스턴스로 운영체제로부터 독립된 자원과 주소 공간을 할당받아 다른 프로세스와 기본적으로 메모리를 공유하지 않습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (3,1,3,'데이터베이스에서 인덱스는 테이블을 풀스캔하지 않고 정렬된 별도 구조를 통해 조건에 맞는 레코드를 빠르게 찾아 조회, 조인, 정렬과 그룹핑 성능을 높이기 위해 사용합니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (4,1,4,'JVM은 자바 바이트코드를 운영체제와 무관하게 실행하는 가상 머신이며 실행 흐름은 자바 컴파일러가 `.java`를 `.class` 바이트코드로 컴파일한 뒤 JVM이 기동되고 ClassLoader가 클래스를 로딩·검증·링킹하여 main부터 실행하는 방식입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (5,1,5,'GC는 JVM이 힙에서 더 이상 참조되지 않는 객체를 자동으로 찾아 메모리를 회수하는 기능입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (6,1,6,'컬렉션 프레임워크는 다양한 자료구조를 표준화된 인터페이스와 구현체로 제공하여 공통된 API로 데이터를 저장·조회·삭제·순회·정렬할 수 있게 하는 라이브러리입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (7,1,7,'제네릭은 클래스·인터페이스·메서드가 사용할 타입을 타입 파라미터로 받아 재사용하게 해주는 기능으로 컴파일 시점에 타입을 명확히 지정해 타입 안정성을 확보합니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (8,1,8,'어노테이션은 클래스·메서드·필드 같은 프로그램 요소에 메타데이터를 부여하는 문법으로 해당 요소의 의미나 설정 정보를 컴파일러·런타임 프레임워크·빌드 도구에 전달합니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (9,1,9,'오버라이딩은 상속 관계에서 자식 클래스가 부모 메서드를 같은 이름으로 재정의하여 다형성을 구현하는 것으로 어떤 메서드가 호출될지는 런타임에 동적 바인딩으로 결정됩니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (10,1,10,'DNS는 도메인 이름을 IP 주소로 변환해주는 인터넷의 전화번호부 시스템입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (11,1,11,'인터넷에서 데이터와 통신을 안전하게 보호하는 암호화 프로토콜로 HTTPS의 핵심 기반입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (12,1,12,'네트워크에서 논리적인 IP 주소를 물리적인 MAC 주소로 변환하는 통신 프로토콜입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (13,1,13,'패킷 수신 측은 1계층에서 물리적 신호를 받아서 7계층 순으로 올라가며 헤더를 하나씩 벗겨내어 순수한 데이터를 추출합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (14,3,2,'프로세스는 OS로부터 할당받은 독립된 메모리 공간을 가지는 실행 단위로 코드, 데이터, 힙, 스택 영역으로 구성되어있고, 스레드는 프로세스 내부에서 자원을 공유하며 실행되는 작업 단위로 스택과 레지스터만 독립적으로 갖습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (15,2,2,'프로세스는 운영체제로부터 자원을 할당 받는 작업의 단위이고 스레드는 그 프로세스 내에서 실행되는 흐름의 단위입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (16,3,8,'''@'' 기호를 사용하여 특별한 의미나 기능을 부여하는 ''메타데이터(데이터에 대한 데이터)''입니다. 프로그램에 추가 정보를 제공하여 코드의 역할을 명시하거나, 컴파일러 및 프레임워크에게 실행 지침을 주는 주석 역할을 수행합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (17,1,14,'코드 영역: 실행할 프로그램의 기계어 코드(명령어)가 저장됩니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (18,1,15,'스레드들이 프로세스의 자원(메모리 등)을 공유하기 때문입니다. 하나의 스레드가 잘못된 메모리 영역에 접근하거나 치명적인 예외를 발생시키면 공유 자원이 오염되거나 프로세스 전체의 안정성이 깨지게 됩니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (19,1,16,'전체 시스템의 성능이나 처리 용량이 특정 구성 요소의 제한으로 인해 낮아지는 현상을 말합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (20,1,17,'둘 이상의 프로세스나 스레드가 공용 자원에 동시 접근하여 실행 순서에 따라 결과가 달라지는 현상을 말합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (21,1,18,'운영체제에서 실행 중인 서로 다른 프로세스들 사이에 데이터를 주고받는 방식입니다. 대표적으로 메시지 큐나 소켓 등이 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (22,1,19,'데이터 전체에 중복이 거의 없고 유니크한 값이 많은 컬럼을 의미합니다. 예시로는 이메일이나 주민등록번호 등이 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (23,1,20,'SQL 쿼리를 가장 빠르고 효율적으로 실행하기 위해 최적의 처리 경로를 수립하는 핵심 엔진입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (24,1,21,'자바에서 C나 C++로 만들어진 라이브러리를 사용할 수 있게 해주는 인터페이스입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (25,1,22,'메서드 영역: 클래스 정보, 변수 이름, 데이터 타입, static 변수, 메소드 코드 등이 저장됩니다.
