INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (31,1,28,'배열은 동일한 타입의 요소를 연속된 메모리 공간에 저장하므로 인덱스로 O(1)에 임의 접근이 가능하지만 중간 삽입/삭제 시 요소 이동이 필요해 O(n)이 걸립니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (32,1,29,'비대칭키 암호화는 두 개의 서로 다른 키를 사용하여 데이터를 암호화/복호화하는 암호화 방법입니다. 대칭키 암호화에 비해 느리지만 비교적 안전하다는 장점이 있습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (33,1,30,'Spring에서 IoC는 객체의 생성과 생명주기 관리, 의존관계 설정을 개발자가 직접 하지 않고 외부에서 담당하도록 제어 흐름을 역전시키는 개념입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (34,1,31,'추상 클래스는 공통 기능과 필드를 함께 묶어 상속 기반으로 재사용하고 필요한 경우 추상 메서드를 통해 하위 클래스가 구현해야 할 기능을 강제하는 목적의 클래스입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (35,1,32,'클래스는 객체를 만들기 위한 설계도로서 객체가 가져야 할 속성과 동작을 정의한 틀입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (36,1,33,'static은 특정 객체에 속하는 값이 아니라 클래스에 고정되어 공유되는 멤버를 의미합니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (37,1,34,'boolean과 byte가 1바이트, char와 short가 2바이트, int와 float가 4바이트, long과 double이 8바이트를 차지합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (38,1,35,'접근 제어자는 public, protected, default, private가 있으며 클래스/필드/메서드의 접근 범위를 제한하는 기능입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (39,1,36,'객체지향은 프로그램을 상태와 행동을 가진 객체들의 상호작용으로 바라보고 기능을 구성하는 프로그래밍 패러다임입니다.
