INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (42,1,39,'JPA 영속성 컨텍스트의 이점은 5가지입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (43,1,40,'TCP는 3-way 핸드셰이크로 연결을 수립하고 시퀀스/ACK 기반으로 재전송과 순서 보장, 흐름 제어, 혼잡 제어를 제공하여 신뢰성 있는 전송을 지원합니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (44,1,41,'컨텍스트 스위칭은 CPU가 실행 중이던 프로세스나 스레드의 상태 정보를 저장하고 다른 작업의 상태 정보를 복원하여 실행 주체를 교체하는 과정입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (45,1,42,'SOLID는 객체지향 설계에서 지켜야 할 5가지 원칙으로 유지보수성과 확장성을 높이기 위한 지침입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (46,1,43,'동일성은 두 객체가 메모리 상에서 완전히 같은 인스턴스인지를 비교하는 개념으로 == 연산자로 판단합니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (47,1,44,'원시 타입은 실제 데이터 값 자체를 저장하며 null을 가질 수 없고 제네릭 타입에 사용할 수 없습니다. 일반적으로 참조 타입보다 메모리 사용이 적고 접근이 빠릅니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (48,1,45,'String은 불변 객체라 문자열 변경 시 새로운 객체가 생성되어 변경이 잦으면 성능이 떨어질 수 있습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (49,1,46,'Checked Exception은 컴파일 시점에 예외 처리를 강제하여 try-catch로 처리하거나 throws로 위임해야 하는 예외입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (50,1,47,'Java 8에서는 람다 표현식과 함수형 인터페이스가 도입되어 함수를 값처럼 전달하고 간결하게 동작을 표현할 수 있게 되었습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (51,1,48,'이은상의 답');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (52,1,49,'이은상의 답');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (53,1,50,'트랜잭션은 데이터베이스의 상태를 변화시키는 작업들을 하나로 묶은 논리적 단위입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (54,1,51,'List는 저장 순서가 유지되고 중복을 허용하며 인덱스로 특정 위치에 접근할 수 있습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (55,1,52,'단방향 암호화는 평문을 해시 값으로 변환할 수는 있지만 해시 과정에서 정보가 손실되어 복호화로 원문을 되돌릴 수 없는 방식입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (56,1,53,'try-with-resources는 Java 7부터 도입된 문법으로 try문에서 선언한 AutoCloseable/Closeable 자원을 블록 종료 시 자동으로 close()하여 finally에서 직접 닫지 않아도 되는 문법입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (57,1,54,'강한 결합은 한 클래스가 다른 클래스의 구현체에 직접 의존하여 내부에서 new로 생성하거나 구체 타입을 고정하는 상태로 의존 대상이 바뀌면 수정 범위가 커져 유지보수가 어려워집니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (58,1,55,'직렬화는 자바 객체의 상태를 저장·전송 가능한 바이트 스트림으로 변환하는 과정이고 역직렬화는 이를 다시 읽어 자바 객체로 복원하는 과정입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (59,1,56,'자바의 동시성 이슈는 멀티 스레드 환경에서 여러 스레드가 공유 자원에 동시에 접근하면서 기대한 값이 나오지 않거나 스레드마다 서로 다른 값을 보게 되는 문제입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (60,1,57,'Mutable 객체는 가변객체로 생성 이후에도 같은 인스턴스의 내부 상태를 직접 변경할 수 있습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (61,1,58,'자바에서 null을 안전하게 다루려면 사용 전 null 체크를 하거나 `Objects.requireNonNull`로 입력 계약을 강제해 null 참조를 빠르게 발견하도록 합니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (62,1,59,'스프링 빈은 스프링 IoC 컨테이너가 생성·등록·관리하는 자바 객체로, 개발자가 `new`로 직접 만들던 객체들을 컨테이너가 대신 생성해 필요한 곳에 주입해주는 대상입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (63,1,60,'스프링 빈은 IoC 컨테이너가 생성한 뒤 의존관계를 주입하고 초기화 콜백을 거쳐 사용되다가 컨테이너 종료 시점에 소멸 전 콜백으로 자원을 정리하는 과정을 가집니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (64,1,61,'스프링 Bean 스코프는 빈이 생성되고 유지되는 라이프사이클 범위를 의미합니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (65,1,62,'IoC 컨테이너는 설정 정보를 바탕으로 빈을 생성·등록하고 빈 사이의 의존관계를 분석해 필요한 객체를 자동으로 주입합니다. 또한 빈의 생명주기와 스코프를 관리합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (66,1,63,'JPA의 Propagation은 이미 진행 중인 트랜잭션이 있을 때 다른 트랜잭션의 수행 방식을 정하는 전파 옵션입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (67,1,64,'3-way handshake는 데이터 전송 전에 클라이언트와 서버가 서로 연결 요청 플래그를 교환하여 통신 가능함을 확인하고 연결을 수립하는 과정입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (68,1,65,'JRE는 자바 프로그램을 실행하기 위한 환경으로 JVM과 표준 라이브러리를 포함하지만 컴파일러 같은 개발 도구는 포함하지 않습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (69,1,66,'Access Token과 Refresh Token을 나눈 이유는 통신 중 탈취될 위험이 큰 Access Token은 유효기간을 짧게 가져가 피해를 최소화하고 대신 Refresh Token으로 Access Token을 재발급해서 사용자가 자주 재로그인하지 않도록 하기 위해서입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (70,1,67,'WebSocket을 사용한 이유는 실시간으로 메시지를 주고받아야 하는 상황에서 HTTP의 요청-응답 구조는 지연과 트래픽 오버헤드가 커지기 때문입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (71,1,68,'폴링이나 롱 폴링, SSE 등의 방법이 있지만 웹소켓의 실시간성과 양방향 통신이라는 특징이 저희 프로젝트에 적합하다고 판단해서 웹소켓을 사용했습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (72,1,69,'스프링의 DI 방식에는 생성자 주입, setter 주입, 필드 주입이 있습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (73,1,70,'컨테이너가 빈을 생성한 뒤 @Autowired가 붙은 주입 지점을 찾아 의존 타입에 맞는 빈을 검색해 주입하고 이후 초기화 단계로 넘어갑니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (74,1,71,'DispatcherServlet은 모든 HTTP 요청을 먼저 받아 HandlerMapping으로 처리할 컨트롤러를 찾고 HandlerAdapter를 통해 해당 컨트롤러를 호출해 처리 결과를 얻는 방식으로 동작합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (75,1,72,'동기는 호출한 쪽이 작업 결과를 받을 때까지 기다리는 방식이라 제어 흐름이 직관적이고 디버깅이 쉽지만 결과가 늦으면 대기 비용으로 처리량이 떨어질 수 있습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (76,1,73,'ACID는 트랜잭션이 지켜야 할 4가지 성질로 원자성, 일관성, 격리성, 지속성이 있습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (77,1,74,'final은 변경을 제한하는 키워드로, 변수에 붙이면 한 번만 초기화되고 재할당이 불가하며 메서드에 붙이면 오버라이딩이 금지되고 클래스에 붙이면 상속이 금지됩니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (78,1,75,'Wrapper class는 기본형을 객체로 다룰 수 있게 감싸는 클래스입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (79,1,76,'Access Token은 프론트에서 사용자 이름/권한 같은 정보를 확인하거나 요청 헤더에 실어 보내는 등 활용도가 높은데 HttpOnly 쿠키에 저장하면 자바스크립트가 접근할 수 없어 이런 처리가 불편해집니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (80,1,77,'WebSocket은 연결만 제공해서 메시지 형식이나 라우팅 규칙을 직접 설계해야 하는데 STOMP를 사용하면 SEND/SUBSCRIBE 같은 표준 프레임과 Pub/Sub 구조로 채팅 메시지 흐름을 일관되게 정의할 수 있습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (81,1,78,'프론트 컨트롤러 패턴은 모든 요청을 하나의 진입점에서 먼저 받아 공통 처리를 수행한 뒤 요청에 맞는 개별 컨트롤러로 위임하는 구조입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (82,1,79,'Servlet Filter는 Servlet 앞단에서 동작하므로 웹 애플리케이션 전반의 공통 처리를 담당하기에 적합합니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (83,1,80,'Spring에서 CORS 에러를 해결하려면 특정 컨트롤러나 메서드에 @CrossOrigin을 붙이거나 WebMvcConfigurer의 addCorsMappings()로 전역 설정을 적용하는 방식이 있습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (84,1,81,'POJO는 특정 기술이나 프레임워크에 종속되지 않고 객체지향 원리에 따라 작성된 순수한 자바 객체입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (85,1,82,'Hash Function은 임의의 키를 해시값으로 변환하는 함수입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (86,1,83,'JWT는 JSON 기반의 정보를 담고 서명한 토큰으로, 주로 인증과 권한 부여에 사용되는 토큰 방식입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (87,1,84,'JPA를 사용하는 이유는 반복적인 SQL 작성과 JDBC 기반 매핑 작업을 줄여 CRUD를 메서드 호출 중심으로 처리할 수 있어 개발 생산성이 높아지기 때문입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (88,1,85,'JPA의 N+1 문제는 연관 엔티티를 조회할 때 처음 1번의 조회 쿼리 이후 조회된 엔티티 수만큼 추가 쿼리가 발생하는 문제입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (89,1,86,'참조복사(얕은복사)는 객체의 참조값만 복사해서 원본과 복사본이 같은 객체를 바라보는 방식입니다. 그래서 복사본의 상태를 변경하면 원본에도 같은 변경이 반영됩니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (90,1,87,'HTTP는 데이터를 평문으로 전송하는 요청-응답 프로토콜이라 중간에서 내용을 탈취하거나 변조할 위험이 있습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (91,1,88,'멀티스레드 프로그래밍은 하나의 프로세스 안에서 여러 스레드가 동시에 작업을 수행하도록 하는 프로그래밍 방식으로 스레드들은 같은 프로세스의 자원을 공유하면서 각자 실행 흐름을 가집니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (92,1,89,'Spring MVC의 컨트롤러는 기본적으로 싱글톤 Bean으로 관리되어서 요청이 여러 번 들어와도 컨트롤러 인스턴스는 하나만 생성되기 때문입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (93,1,90,'Spring Web MVC는 여러개의 서블릿을 직접 두는 대신 DispatcherServlet이라는 하나의 Front Controller Servlet이 모든 요청을 먼저 받도록 구성했습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (94,1,91,'필터는 서블릿 영역에서 동작하므로 여기서 발생한 예외는 필터 내부에서 직접 try-catch로 응답을 만들거나 에러 처리 경로로 넘겨야 합니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (95,1,92,'대표적인 방법으로는 Bean 초기화 직후 실행되는 @PostConstruct와 애플리케이션이 완전히 시작된 뒤 실행되는 CommandLineRunner 또는 ApplicationRunner가 있습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (96,1,93,'객체가 생성되는 시점에 필요한 값이 모두 들어와 완전한 상태로 생성되도록 보장할 수 있기 때문입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (97,1,94,'세션 방식은 로그인 상태를 서버 메모리나 세션 저장소에 보관해야 해서 사용자가 많아질수록 서버 부하도 커집니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (98,1,95,'웹 서버는 HTTP 요청을 받아 정적 리소스를 전달하는 역할에 적합합니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (99,1,96,'Spring 애플리케이션은 main() 메서드에서 SpringApplication.run()을 호출하면서 시작되며 이때 스프링 부트가 애플리케이션 타입을 판단하고 실행에 필요한 Environment와 ApplicationContext를 준비합니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (100,1,97,'트랜잭션 격리 수준은 동시에 여러 트랜잭션이 실행될 때 서로의 변경 내용을 어디까지 볼 수 있게 할지를 정하는 기준입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (101,1,98,'정규화는 데이터 중복을 줄이고 데이터 구조를 올바르게 분리해서 무결성을 높이는 과정입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (102,1,99,'JOIN은 분리된 여러 테이블을 공통 컬럼을 기준으로 연결해 원하는 데이터를 함께 조회하는 방법입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (103,1,100,'스택과 큐는 대표적인 선형 자료구조입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (104,1,101,'우선순위 큐는 우선순위가 높은 데이터가 먼저 나가는 자료구조입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (105,1,102,'Tree는 노드와 간선으로 이루어진 계층형 비선형 자료구조입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (106,1,103,'OAuth는 사용자의 아이디와 비밀번호를 직접 넘기지 않고 특정 리소스에 대한 접근 권한만 토큰 형태로 위임할 수 있게 해주는 인가 표준입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (107,1,104,'JWT는 서버가 토큰에 사용자 정보와 권한을 담아 직접 인증을 처리하는 방식이고 주로 자체 로그인 이후 stateless한 인증에 사용됩니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (108,1,105,'SQL Injection은 사용자 입력값이 검증되지 않은 채 SQL 쿼리에 직접 포함될 때 공격자가 SQL 문을 주입해 데이터베이스를 비정상적으로 조작하는 공격입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (121,3,1,'사용자가 웹브라우저에 URL을 입력하면 DNS를 통해 IP로 변환하고 http''s''의 경우 TCP와 서버와 클라이언트간의 인증 및 암호화 키를 공유하여 안전한 통신 채널을 만드는 과정인 TLS을 통해 안정적인 연결을 맺은 후 HTTP요청/응답을 통해 서버로부터 자원을 받아와 화면에 렌더링하는 과정을 거치게됩니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (122,3,3,'WHERE 조건 검색 속도 개선, JOIN 성능 향상, ORDER BY, GROUP BY 최적화를 위해서 사용됩니다. 조회성능이 향상되며 대용량 데이터에서 효과가 크다는 장점이 있지만 저장 공간을 추가적으로 사용해야하며 과도한 인덱스는 오히려 성능을 저하할 수 있다는 단점이 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (123,3,4,'JVM은 Class Loader, Runtime Data Area, Execution Engine, Garbage Collector로 구성되어 바이트코드를 해석·최적화해 실제 프로그램을 실행합니다. Java는 소스 코드가 자바 컴파일러에 의해(javac) 바이트코드로 컴파일되고 JVM에서 운영체제에 맞는 기계어로 변환되어 실행됩니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (124,3,5,'GC는 garbage collector의 약자로 JVM이 힙 영역에서 사용되지 않는 객체를 자동으로 제거해 메모리를 관리하는 기능입니다. 이로써 메모리 누수를 방지하고 개발자의 메모리 관리 부담 감소할 수 있어 안정적인 애플리케이션 실행이 가능합니다. gc root에서부터 참조할 수 있는 객체에 전부 mark를 하며 mark가 안된 객체에 한해서 객체들을 제거하고 메모리를 정리합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (125,3,6,'데이터 객체를 효율적으로 관리하고 사용하기 위해 java.util에서 제공하는 표준화된 클래스 및 인터페이스 집합입니다. 일관된 API를 제공하고 가변적인 저장공간을 사용할 수 있으며 API코드가 고도로 최적화되어있다는 장점이 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (126,3,7,'리스트나 해시 같은 컬렉션 클래스나 메서드를 ''정의''할 때 타입을 고정하지 않고 사용할 때 구체적인 타입을 지정하는 기법으로 코드 재사용성을 높이고, 컴파일 시 타입 체크를 하여 형변환 에러를 방지하며, 데이터 타입을 동적이고 안전하게 관리할 수 있는 특징이 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (127,3,9,'오버라이딩(Overriding)은 상속받은 메서드의 내용만 변경하는 것입니다. 매개변수의 타입과 순서, 리턴타입, 클래스명이 전부 다 같아야하며 자식 클래스에서 오버라이딩하는 메서드의 접근 제어자는 부모 클래스보다 더 좁게 설정할 수 없다는 특징이 있습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (128,3,11,'TLS(Transport Layer Security, 전송 계층 보안)는 인터넷상에서 데이터를 안전하게 전송하기 위해 데이터를 암호화하고 무결성을 보장하는 보안 프로토콜입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (129,3,15,'스레드 중 하나가 죽으면 프로세스 전체가 종료되는 주된 이유는 스레드들이 메모리(힙, 데이터, 코드 영역)와 자원을 공유하기 때문입니다. 하나의 스레드가 심각한 오류(예: 메모리 오염, Segfault)를 일으키면 해당 프로세스의 전체 메모리 공간이 더 이상 안전하지 않게 되어 운영체제가 프로세스 전체를 종료시킵니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (130,3,16,'병목현상(Bottleneck)은 전체 시스템의 성능이나 처리 속도가 가장 느린 하나의 구성 요소(병의 목 부분)에 의해 제한받는 현상을 의미합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (131,2,1,'먼저 브라우저는 DNS서버를 통해 도메인의 IP 주소를 찾아냅니다. 만약 캐시에 기록이 없으면 루트 서버부터 순차적으로 물어봐서 찾아옵니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (132,2,3,'인덱스는 책의 목차처럼 검색 성능을 높이기 위해 사용하는 기술입니다. B-Tree 구조를 통해 조회 속도를 획기적으로 줄일 수 있다는 장점이 있습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (133,2,4,'JVM은 크게 클래스로더, 메모리 영역, 실행 엔진으로 구성됩니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (134,2,5,'GC는 힙 영역에서 사용하지 않는 객체를 자동으로 삭제해주는 프로세스입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (135,3,28,'배열은 같은 타입의 데이터가 연속된 메모리 공간에 저장된 자료구조로 접근이 빠르지만 삽입/삭제가 비효율적이고, 링크드 리스크는 노드가 연결된 자료구조로 삽입/삭제는 빠르지만 순차탐색만 가능하다는 특징이 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (136,3,29,'대칭키 암호화는 하나의 키로 암호화와 복호화를 모두 수행하며 속도가 빠르지만 키 전달중 탈취가 발생할 수 있다는 단점이 있습니다. 대표적인 예시로 AES 암호화 알고리즘이 있습니다. 비대칭 암호화는 속도는 느리지만 안전한 키 교환이 가능하며 기밀성/인증/부인 방지 기능을 제공한다는 장점이 있습니다. 대표적으로 RSA, DSA 알고리즘이 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (137,3,30,'DI(Dependency Injection)는 필요한 객체를 직접 생성하지 않고 외부에서 주입받는 방식이고 IoC(Inversion of Control)는 객체 생성과 관리의 제어권이 Spring Container로 넘어가는 것입니다. 컴포넌트 스캔을 통해 Bean을 등록하고 의존성을 분석한 후 적절한 Bean을 찾아 주입하는 흐름으로 동작합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (138,2,6,'컬렉션 프레임워크는 다수의 데이터를 쉽고 효율적으로 처리할 수 있도록 표준화된 클래스의 집합입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (139,3,31,'인터페이스는 기능의 명세만 정의한 설계도와 같습니다. 하나의 클래스는 여러 인터페이스를 구현하는 다중 구현이 가능합니다. 따라서 구현체 교체와 확장에 유리합니다. 반면 추상클래스는 공통 상태와 일부 구현을 포함할 수 있어 코드 재사용에 적합하지만 단일 상속만 가능합니다. 따라서 계층 구조를 표현할 수 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (140,3,32,'클래스는 객체를 생성하기 위한 설계도이며 객체는 클래스에 의해 생성된 실제 인스턴스입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (141,3,24,'Minor GC는 young영역에서 동작하는 gc로 Major gc보다 자주 동작합니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (142,3,25,'살아있는 객체를 식별하기 위해 출발점으로 삼는 최상위 참조점으로 스택, 정적 필드 등 실행 중인 코드에서 직접 접근 가능한 객체들을 말함.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (143,3,26,'인터페이스 구현체는 인터페이스를 실제로 작동하는 코드인 클래스로 구체화한 것입니다. 대표적인 예시로 List인터페이스를 구현한 ArrayList, LinkedList 구현체등이 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (144,3,27,'자식 클래스에서 부모 클래스의 메서드를 오버라이딩할 때, 반환 타입을 부모의 타입에서 자식의 타입(하위 타입)으로 더 구체적으로 변경할 수 있는 기능을 말합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (145,2,7,'데이터 타입을 클래스 내부가 아닌 외부에서 지정해주는 기법입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (146,2,8,'어노테이션은 소스 코드에 메타데이터를 추가하여 컴파일러나 런타임에 정보를 제공하는 기능입니다. 주석과는 다르게 코드의 동작에 영향을 미칠 수 있습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (147,2,9,'오버로딩은 매개변수만 바꿔서 같은 이름의 메서드를 여러 개 만드는 것으로 컴파일 시점에 결정됩니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (148,3,33,'static은 객체가 아닌 클래스에 속하는 멤버로 모든 인스턴스가 공유합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (149,2,10,'도메인 이름을 IP주소로 변환해주는 시스템입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (150,2,11,'인터넷통신을 암호화하는 프로토콜입니다. HandShake 과정을 통해 서로 신원을 확인하고 암호화키를 교환해서 안전하게 데이터를 주고받습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (151,2,12,'논리적인 IP 주소를 물리적인 Mac주소로 변환하는 프로토콜입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (152,2,13,'데이터를 받을 때 물리 계층부터 응용 계층까지 올라가면서 헤더를 하나씩 벗겨내며 데이터를 확인하는 과정입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (153,3,34,'자바의 원시 타입은 byte(1), boolean(1), short(2), char(2), int(4), float(4), double(8), long(8)이 있으며 각각 1~8바이트 크기를 가집니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (154,3,35,'public, protected, default, private이 있으며 public은 어디서든 접근 가능하고 protected는 같은 패키지와 상속받은 곳에서 접근 가능하며 default는 같은 패키지에서만 접근 가능합니다. private은 같은 클래스 내부에서만 접근 가능합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (155,2,14,'코드 영역에는 실행할 명령어가 저장됩니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (156,2,15,'스레드끼리는 메모리 공간을 공유하기 때문입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (157,2,16,'전체 시스템 성능이 가장 느린 하나의 요소 때문에 저하되는 현상입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (158,2,17,'두 개 이상의 프로세스나 스레드가 공유 자원에 동시에 접근하여 접근 순서에 따라 결과가 달라지는 문제입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (159,2,18,'프로세스들은 메모리를 공유하지 못하므로 프로세스끼리 데이터를 주고 받기 위해 사용하는 통신 메커니즘 입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (160,2,19,'데이터의 중복이 적고 유니크한 값이 많을수록 선택도가 높습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (161,2,20,'옵티마이저는 SQL을 가장 빠르고 효율적으로 실행하기 위해 최적의 경로를 결정하는 DBMS의 핵심 엔진입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (162,2,21,'자바코드에서 C나 C++로 만들어진 라이브러리를 호출해서 사용할 수 있게 해주는 인터페이스 입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (163,2,22,'스택 영역은 지역 변수, 메서드 영역은 클래스와 Static 변수, 힙 영역은 new로 생성된 인스턴스가 저장됩니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (164,2,23,'처음 생성된 객체는 Young 영역에 있다가 GC에서 계속 살아남으면 Old영역으로 이동하는데 이를 승격이라고 합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (165,2,24,'Minor GC는 Young 영역이 꽉 찼을 때 발생하고 속도가 빠르고 빈번합니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (166,3,36,'객체지향은 현실 세계의 개념을 객체 단위로 모델링하여 데이터와 행위를 하나로 묶는 프로그래밍 패러다임(인식체계, 틀)입니다. 4대 특징에는 캡슐화, 상속, 다형성, 추상화가 있습니다. 캡슐화는 내부 구현을 보호하고 외부로 공개된 메서드를 통해서만 수정이 가능하도록 하는 것입니다. 상속은 기존 클래스의 속성과 동작을 물려받아 새로운 클래스를 확장하는 개념으로 계층 구조를 표현할 수 있습니다. 다형성은 동일한 인터페이스로 다양한 객체를 처리할 수 있다는 특징이며 추상화는 공통적인 속성과 동작만을 정의하고 세부 구현은 감추어 복잡성을 줄이는 개념입니다. 이를 통해 유지보수성과 확장성이 높은 구조를 설계할 수 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (167,2,25,'GC가 살아있는 객체인지 판단하는 시작점입니다. 실행 중인 스레드의 지역변수나 Static 변수 등이 해당됩니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (168,2,26,'인터페이스는 설계도이고 구현체는 그 기능을 실제로 코드로 만든 클래스입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (169,2,27,'오버라이딩할 때, 부모 메서드의 반환 타입보다 더 구체적인 자식 타입으로 바꿔서 반환할 수 있는 기능입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (170,2,28,'가장 큰 차이는 메모리 구조입니다. 배열은 연속된 공간에 저장되어 인덱스로 조회는 빠르지만 중간에 데이터를 넣거나 뺄 때는 뒤의 데이터를 다 밀어야 해서 느립니다.<br>
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (171,2,29,'대칭키는 암호화와 복호화에 같은 키를 씁니다. 연산 속도가 빠르지만 상대방에게 키를 안전하게 전달하는 게 어렵습니다.<br> 비대칭키는 공개키와 개인키, 두 개의 키를 씁니다. 공개키로 잠그고 개인키로 여는 방식이라 키 관리는 안전하지만 연산 과정이 복잡해 속도가 느리다는 단점이 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (172,3,37,'객체가 자신이 필요로 하는 의존 객체를 직접 생성하지 않고, 외부에서 주입받기 때문입니다. 이로 인해 구체적인 클래스에 의존하지 않고 인터페이스에 의존하게 되어 코드의 유연성과 유지보수성이 크게 향상됩니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (173,3,38,'클래스 로더(Class Loader)에 의해 클래스가 처음 사용될 때 Static 영역(Method Area)에 단 한 번 로드되어, 인스턴스(객체) 생성 여부와 무관하게 프로그램이 종료될 때까지 메모리에 고정(static)되기 때문입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (174,3,39,'JPA 영속성 컨텍스트는 애플리케이션과 DB 사이에서 객체를 관리하는 계층으로, 크게 5가지 이점이 있습니다.<br>
(1차 캐시) 같은 트랜잭션 내에서 ID가 같은 엔티티는 메모리에서 바로 조회하여 **DB 접근 횟수를 줄입**니다.<br>
(동일성 보장) == 비교 시 같은 객체임을 보장하여 **데이터 정합성을 유지**합니다.<br>
(쓰기 지연) 변경 사항을 즉시 DB에 보내지 않고 모았다가 커밋 시점에 한 번에 반영하여 **네트워크 비용을 줄입**니다.<br>
(변경 감지) 객체의 값만 바꾸면 커밋 시점에 자동으로 Update SQL이 생성되어, **수정 쿼리를 직접 작성할 필요가 없습**니다.<br>
(지연 로딩) 연관된 객체를 실제 사용하는 시점에 가져오도록 프록시를 활용해 **불필요한 데이터 조회를 방지**합니다.<br>');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (175,3,40,'tcp는 인터넷상에서 컴퓨터들간에 데이터를 안전하게 유실없이 주고받을 수 있도록 하는 연결지향형 프로토콜입니다. 따라서 데이터를 전송하기 전에 3-way handshake를 통해서 안정적으로 데이터를 보낼 수 있는 상태를 만든 후 데이터를 전송하게됩니다. 만약 패킷이 중간에 유실이 된다면 재요청하고 순서를 다시 맞추어 높은 신뢰도를 보장합니다. 반면 udp는 비연결형 데이터그램 프로토콜로 데이터의 유실이 있을 수 있지만 속도가 빨라서 온라인 게임이나 DNS 또는 온라인 스트리밍등에 주로 사용됩니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (176,3,41,'컨텍스트 스위칭은 CPU가 실행 중인 프로세스나 스레드를 변경하는 과정이며, 이때 레지스터 상태 저장과 복원이 발생해 오버헤드가 발생합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (177,3,42,'SOLID는 객체 지향 설계 원칙으로 하나의 클래스는 하나의 책임만 져야하며 기능 추가시 기존 코드에 변화 없이 쉽게 확장이 가능해야하고 자식은 부모를 대체 가능해야한다는 것입니다. 또한 클래스는 불필요한 인터페이스 구현이 없어야 하며 구체화된 클래스가 아닌 추상화에 의존해야한다는 내용입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (178,3,43,'동일성은 객체의 참조값인 메모리 주소를 비교하는 것이고, 동등성은 equals()를 통해 객체의 실제적인 값을 비교하는 것입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (179,3,44,'원시타입은 실제 값을 스택 메모리에 저장하며 참조타입은 실제 값은 힙 영역에 저장하고 데이터의 주소값을 스택에 저장합니다. 따라서 원시타입은 null을 가질 수 없으며 참조타입에는 null이 저장 가능합니다. 또한 참조값은 주소 탐색이 필요하므로 원시타입보다 성능이 떨어집니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (180,3,45,'String은 불변 객체로 문자열 상수 풀과 보안, 해시 안정성을 위해 설계되었습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (181,3,46,'Checked Exception은 컴파일 시 예외 처리를 강제하며, 복구 가능성이 있는 예외를 표현하기 위해 사용됩니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (182,3,47,'Java 8은 람다 표현식과 Stream API를 통해 함수형 프로그래밍을 도입했고, Optional을 통해 null 안정성을 개선했으며, 인터페이스 내부에 default method를 추가하고 새로운 날짜 API를 추가해 기존 Java의 한계를 보완한 중요한 버전입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (183,3,48,'TCP에서 시퀀스 번호(Sequence Number, Seq)는 전송되는 데이터의 순서를 보장하기 위해 각 세그먼트(패킷)에 부여하는 고유 번호이며, ACK(Acknowledgment Number, 응답 번호)는 수신자가 데이터를 잘 받았음을 확인하고 다음에 받을 데이터를 알리는 번호입니다. 이 둘은 TCP의 핵심인 데이터 순서 재정렬, 오류 복구, 신뢰성 있는 통신을 가능하게 합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (184,3,50,'트랜잭션은 하나의 논리적 작업 단위로, 모두 성공하거나 모두 실패해야 하는 작업 묶음입니다. ACID 특성을 통해 데이터의 무결성과 일관성을 보장합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (185,3,49,'Process Control Block (프로세스 제어 블록)의 약자로, 운영체제가 프로세스를 관리하기 위해 프로세스의 핵심 정보를 저장하는 데이터 구조입니다. 입니다. 프로세스 생성 시 생성되어 메모리(커널 스택)에 저장되며, 문맥 교환(Context Switching) 시 프로세스 상태를 저장/복구하는 데 사용됩니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (186,2,30,'**IoC(제어의 역전)** 는 스프링컨테이너가 객체의 생성과 생명주기를 관리하는 것이고
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (187,2,31,'둘은 사용하는 목적이 다릅니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (188,2,32,'클래스는 객체를 만들기 위한 설계도 즉 틀입니다. 객체는 그 설계도를 바탕으로 실제 메모리에 생성된 실체(Instance)입니다');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (189,2,33,'static은 고정된이라는 뜻으로 객체 생성 없이 클래스가 로드될 때 메모리에 딱 한 번 생성되는 것을 말합니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (190,2,34,'자바에는 총 8가지 원시 타입이 있습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (191,2,35,'접근 범위가 넓은 순서대로 4가지가 있습니다. 어디서든 접근 가능한 public, 같은 패키지거나 상속받은 자식 클래스에서 접근 가능한 protected, 아무것도 안 썼을 때 같은 패키지에서만 접근 가능한 default, 그리고 해당 클래스 내부에서만 접근할 수 있는 private이 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (192,2,36,'- 첫째, 상속은 부모 클래스의 기능을 자식이 물려받아 재사용하는 것입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (193,2,37,'DI를 사용하지 않으면 객체 안에서 직접 new로 객체를 생성해야 해서 나중에 객체를 교체할 때 코드를 다 수정해야 함
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (194,2,38,'static 멤버는 객체가 아니라 클래스에 소속되기 때문
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (195,3,51,'List는 순서를 유지하고 중복을 허용하는 컬렉션인 반면, Set은 일반적으로 순서를 보장하지 않고 중복을 허용하지 않는 컬렉션입니다. Set의 경우 순서를 유지하고자 한다면 LinkedHashSet을 사용할 수 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (196,3,52,'단방향 암호화는 복호화가 불가능한 해시 기반 암호화 방식으로, 주로 비밀번호 저장에 사용됩니다. 대표적으로 SHA-256알고리즘이 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (197,3,53,'try-with-resources는 AutoCloseable을 구현한 자원을 자동으로 해제해주는 구문입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (198,3,54,'강한 결합이란 구체 클래스에 직접 의존하여, 구현 변경 시 사용하는 코드도 함께 수정해야 하는 상태이며 느슨한 결합이란 인터페이스에 의존하고 객체 생성을 외부로 분리하여, 구현 변경 시 사용하는 코드 수정이 필요 없는 구조입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (199,3,55,'직렬화는 객체를 바이트 스트림으로 변환하는 것이고, 역직렬화는 이를 다시 객체로 복원하는 과정입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (200,3,56,'동시성 이슈는 여러 스레드가 공유 자원에 동시에 접근할 때 데이터의 일관성과 정합성이 깨지는 현상으로 synchronized나 Lock, AtomicInteger 등을 통해 해결할 수 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (201,3,57,'Mutable 객체는 상태 변경이 가능하고, Immutable 객체는 생성 이후 상태 변경이 불가능합니다. Mutable객체는 데이터 수정 시 새로운 객체를 생성하지 않아 메모리 overhead가 적고 효율적입니다. Immutable 객체는 안정적이지만 변경이 잦은 경우에는 메모리 사용량이 증가할 수 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (202,3,58,'null은 NullPointerException을 유발할 수 있기 때문에 Optional 사용, 명시적 null 체크, @NonNull 어노테이션 등을 통해 안전하게 다루는 것이 중요합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (203,3,59,'Spring Bean은 Spring IoC 컨테이너가 생성하고 관리하는 객체입니다. 개발자가 직접 new로 생성하는 것이 아니라, 컨테이너가 객체의 생성, 의존성 주입, 생명주기 관리를 담당합니다. 기본적으로 싱글톤으로 관리되며, @Component나 @Bean 등을 통해 등록할 수 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (204,3,60,'먼저 BeanDefinition이라는 메타정보가 생성됩니다. 이후 Reflection으로 객체가 생성되고, 의존성 주입이 이루어집니다. 그 다음 (@PostConstruct 같은) 초기화 메서드가 실행되며, 필요하다면 (BeanPostProcessor를 통해) 프록시가 생성됩니다. 컨테이너 종료 시에는 소멸 콜백이 호출됩니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (205,3,61,'Spring Bean Scope는 Bean의 생명 범위를 의미합니다. 기본은 Singleton으로 컨테이너당 하나의 인스턴스를 공유합니다. Prototype은 요청할 때마다 새로운 객체를 생성하며, Web 환경에서는 request, session, application scope도 지원합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (206,3,62,'IoC 컨테이너는 객체 생성과 의존성 주입을 담당하며, Bean의 생명주기와 싱글톤 관리, AOP 적용까지 수행합니다. 이를 통해 객체 간 결합도를 낮추고 유지보수성을 향상시킵니다. <br>
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (207,3,63,'트랜잭션 전파는 트랜잭션 동작 중 다른 트랜잭션을 호출할 때 호출된 트랜잭션이 기존 트랜잭션과 어떤 관계를 맺을지 결정하는 설정입니다. 기본값인 REQUIRED는 기존 트랜잭션에 참여하고 없으면 새로 생성합니다. REQUIRES_NEW는 항상 새로운 트랜잭션을 생성하며, MANDATORY는 기존 트랜잭션이 반드시 필요합니다. 그 외에는 SUPPORTS, NOT SUPPORTED, NESTED, NEVER가 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (208,3,64,'TCP의 3-way handshake는 데이터 전송 전 클라이언트와 서버가 연결을 수립하는 과정입니다. <br>
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (209,3,65,'JRE는 자바 프로그램 실행을 위한 환경이며 JVM과 라이브러리를 포함합니다. JDK는 JRE에 컴파일러를 포함한 개발 도구가 추가된 것으로, 자바 개발을 위해 필요합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (210,3,105,'사용자 입력값에 악의적인 SQL 구문을 삽입해 데이터베이스를 비정상적으로 조작하는 공격 기법입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (211,3,104,'JWT와 OAuth는 서로 다른 레이어의 개념으로 JWT는 인증 정보를 담는 토큰의 형식이고, OAuth는 제3자 앱에 권한을 위임하는 프로토콜입니다. 실무에서는 OAuth로 소셜 로그인 처리 후 사용자 정보를 확인하고, 이후 서비스 내부에서는 JWT를 발급해 인증하는 방식으로 두 가지를 조합해서 사용합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (212,3,103,'OAuth는비밀번호를 공유하지 않고도, 특정 서비스(Google, Kakao 등)의 데이터에 접근할 수 있는 ''권한''을 안전하게 위임받기 위한 표준 프로토콜입니다. 대표적으로 소셜로그인에서 사용됩니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (213,3,102,'Tree는 계층적 구조를 표현하는 비선형 자료구조입니다. 노드(Node)와 간선(Edge)으로 구성되며 사이클이 없습니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (214,3,101,'Heap은 완전 이진 트리 기반의 자료구조로 삽입과 삭제는 O(log n)이고 Min Heap, Max Heap 각각의 최솟값/최댓값 조회는 O(1)입니다. Priority Queue는 Heap을 내부 구현으로 사용하며, FIFO가 아닌 우선순위 순서로 데이터를 꺼내는 자료구조입니다.
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (215,3,100,'Stack은 LIFO(Last In First Out) 구조로 마지막에 삽입한 데이터가 먼저 삭제됩니다. 함수 호출 스택, 괄호 유효성 검사, 브라우저 뒤로가기 등에 사용됩니다. Queue는 FIFO(First In First Out) 구조로 먼저 삽입한 데이터가 먼저 삭제됩니다. BFS, 프린터 대기열, Kafka 같은 메시지 큐에 사용됩니다. 두 자료구조 모두 삽입과 삭제가 O(1)입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (216,3,99,'JOIN은 두 개 이상의 테이블을 특정 조건으로 결합하는 연산입니다. JOIN 성능을 위해 조인 조건 컬럼에 인덱스를 설정해야 하고, 작은 테이블을 기준으로 WHERE 조건으로 먼저 데이터를 줄인 후 JOIN하는 것이 좋습니다.<br>
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (217,3,98,'정규화는 데이터 중복을 제거하고 이상 현상(Anomaly)을 방지하기 위해 테이블을 올바른 구조로 분리하는 과정입니다. 다만 정규화가 지나치면 JOIN이 많아져 성능이 저하될 수 있으므로, 실무에서는 조회 성능이 중요한 경우 반정규화를 함께 고려합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (218,3,97,'트랜잭션 격리 수준은 동시에 실행되는 트랜잭션 간의 데이터 가시성을 제어하는 수준입니다. 낮은 순서로 READ UNCOMMITTED, READ COMMITTED, REPEATABLE READ, SERIALIZABLE 4단계가 있습니다. 격리 수준이 낮을수록 Dirty Read, Non-Repeatable Read, Phantom Read와 같은 문제가 발생할 수 있고, 높을수록 동시성 성능이 낮아지는 문제가 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (219,3,96,'Spring Boot는 SpringApplication.run() 호출을 통해 내장 WAS를 실행하고, 자동 설정(Auto-configuration)과 컴포넌트 스캔을 거쳐 IoC 컨테이너를 초기화하여 애플리케이션을 구동합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (220,3,95,'웹 서버는 HTML, 이미지 등 정적 콘텐츠를 처리하는 HTTP 기반 서버(Apache, Nginx)이며, WAS(Web Application Server)는 DB 조회, 로직 처리 등 동적 콘텐츠를 생성하는 서버(Tomcat, Jeus)입니다. 보통 웹 서버가 앞단에서 정적 파일을 처리하고, 복잡한 동적 요청을 WAS에 넘기는 구조로 부하를 분산합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (221,3,94,'세션 방식은 서버 메모리를 사용하기 때문에 동시 접속자가 늘어나면 서버에 부하가 커집니다. 저희 서비스의 메신저 기능이 있어 접속자가 많을 경우를 염두해 상대적으로 서버 부하 관리에 유리한 JWT 방식을 사용하게 되었습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (222,3,93,'생성자 주입을 권장하는 이유는 final 키워드를 사용해 불변성을 보장할 수 있으며 순환 참조를 방지할 수 있고 (Spring 컨텍스트 없이 생성자로 Mock을 바로 주입할 수 있어) 단위 테스트가 용이하기 때문입니다. 또한 객체 생성 시점에 모든 의존성이 반드시 주입되어야 하므로 필수 의존성이 명확해지고 NullPointerException을 방지할 수 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (223,3,91,'Interceptor는 Spring 컨텍스트 안에 있어서 예외가 발생하면 DispatcherServlet이 잡아 @ControllerAdvice로 처리할 수 있습니다. 반면 Filter는 Spring 컨텍스트 바깥 Tomcat 레벨에서 동작하므로 @ControllerAdvice가 동작하지 않습니다. Filter의 예외는 세 가지 방법으로 처리할 수 있는데, Filter 내부에서 직접 HttpServletResponse에 응답을 작성하거나, 예외 처리 전담 Filter를 체인 맨 앞에 배치하거나, HandlerExceptionResolver를 주입받아 Spring의 예외 처리 체계에 위임하는 방법이 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (224,3,90,'Request별로 생성해주어야 하는 Java Servlet과 다르게 Spring은 DispatcherServlet 하나만 등록해 모든 요청을 받는 프론트 컨트롤러 패턴으로 구현되어 있습니다. DispatcherServlet은 HandlerMapping, HandlerAdapter, ViewResolver를 두어 요청을 적절한 Controller에 위임하고 응답을 처리합니다. 이렇게 하나의 객체에서 모든 요청을 먼저 처리하기 때문에 재사용성이 좋고 관리가 용이합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (225,3,89,'스프링 프레임워크는 기본적으로 POJO기반의 모든 Bean을 Singleton Scope로 관리하기 때문입니다. 따라서 Spring 컨테이너가 시작될 때 딱 1개만 생성하고, 모든 요청이 그 1개의 인스턴스를 공유하게됩니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (226,3,88,'멀티스레드 프로그래밍은 하나의 프로세스 안에서 여러 스레드가 동시에 실행되도록 하는 방식입니다. CPU를 효율적으로 활용해 성능과 응답성을 높일 수 있지만, 여러 스레드가 공유 자원에 동시 접근할 때 경쟁 조건이나 교착 상태 같은 문제가 발생할 수 있습니다. 이를 해결하기 위해 synchronized, AtomicInteger, lock과 같은 동기화 메커니즘을 사용합니다.<br>
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (227,3,87,'HTTP는 데이터를 평문으로 전송하는 프로토콜이고, HTTPS는 HTTP에 TLS 암호화를 추가한 프로토콜입니다. HTTPS는 통신 전 SSL Handshake를 통해 암호화 키를 교환하는데, 비대칭키(공개키/개인키)로 대칭키를 안전하게 전달하고 이후 실제 통신은 빠른 대칭키로 처리합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (228,3,86,'깊은 복사는 객체와 내부의 모든 중첩 객체까지 새롭게 생성해 완전히 독립적인 복사본을 만듭니다. 반면, 얕은 복사는 객체의 참조값(메모리 주소)만 복사해 원본과 복사본이 같은 객체를 가리키므로, 한쪽을 수정하면 다른 쪽도 영향을 받습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (229,3,85,'N+1 문제는 한 번의 쿼리로 N개의 엔티티를 조회했으나, 각 엔티티의 연관 데이터를 가져오기 위해 N번의 추가 쿼리가 발생하는 성능 문제입니다. 주로 LAZY 로딩 상황에서 연관 엔티티에 접근할 때 발생합니다. 해결 방법으로는 JPQL의 Fetch Join으로 한 번에 조회하거나, @BatchSize를 설정해 조회하는 방법이 있습니다.<br>
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (230,3,84,'JPA를 사용하는 이유는 ORM을 통해 객체와 관계형 DB 간의 패러다임 불일치를 해결해주며 SQL 자동 생성으로 반복 작업이 줄어 생산성이 향상됩니다. Dialect 설정만 바꾸면 DB 종류에 독립적인 코드 작성이 가능하며 영속성 컨텍스트가 제공하는 1차 캐시와 변경 감지로 성능 최적화와 편리한 엔티티 관리가 가능합니다. <br>
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (231,3,83,'JWT는 Header, Payload, Signature 세 부분으로 구성된 토큰 기반 인증 방식입니다. 서버가 상태를 저장하지 않아도 되는 Stateless 구조라 서버 확장에 유리하고 DB 조회가 불필요합니다. 다만 한번 발급된 토큰은 만료 전까지 무효화하기 어렵기 때문에, 수명이 짧은 AccessToken과 수명이 긴 RefreshToken을 함께 사용하는 방식으로 보완합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (232,3,82,'해시 함수는 임의의 데이터를 고정된 크기의 해시값으로 변환하는 함수이고, 해시 테이블은 이 해시값을 배열의 인덱스로 사용해 키-값 쌍을 저장하는 자료구조입니다. 평균 O(1)으로 빠른 조회 성능이 장점이지만, 서로 다른 키가 같은 해시값을 갖는 해시 충돌이 발생할 수 있습니다. 이러한 문제는 chaining이나 open addressing으로 해결할 수 있습니다.<br>
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (233,3,81,'POJO는 특정 프레임워크나 기술에 종속되지 않은 순수 Java 객체입니다. Spring에서는 어노테이션이 붙은 클래스들이 모두 POJO가 될 수 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (234,3,80,'CORS는 브라우저의 동일 출처 정책으로 인해 다른 출처의 API 요청이 차단되는 현상입니다. Spring에서는 세 가지 방법으로 해결할 수 있는데, 컨트롤러 단위에서는 @CrossOrigin를 이용할 수 있고 전역적인 설정은 addCorsMappings을 override해서 사용할 수 있습니다. Spring Security 사용 시에는 SecurityFilterChain을 빈으로 등록하여 사용할 수 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (235,3,79,'Servlet Filter는 Servlet 컨테이너 레벨(DispatcherServlet 이전)에서 동작해 Spring과 무관하게 모든 요청을 처리하며 Request/Response 객체 자체를 변경할 수 있습니다. 반면 Spring Interceptor는 Spring 컨테이너 안에서 DispatcherServlet 이후에 동작하므로 Spring Bean 주입이 자유롭고 (preHandle, postHandle, afterCompletion으로) 세밀한 제어가 가능합니다. (따라서 인코딩이나 CORS처럼 서블릿 수준의 공통 처리는 Filter를, 인증/인가나 로깅처럼 Spring의 기능이 필요한 공통 처리는 Interceptor를 사용합니다.)');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (236,3,78,'프론트 컨트롤러 패턴은 모든 클라이언트 요청을 단일 진입점에서 받아 공통 처리(인증, 로깅 등)를 수행한 뒤 적절한 핸들러로 위임하는 패턴입니다. Spring MVC에서는 DispatcherServlet이 이 역할을 담당합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (237,3,77,'순수 WebSocket을 사용할 경우 메시지 형식과 구독, 브로드캐스트 구조를 직접 설계해야 하므로 복잡도가 증가합니다. STOMP를 사용하면 목적지 기반 구독 모델과 브로커 개념이 명확해지고, Spring에서는 STOMP를 지원하여 @MessageMapping, @SendTo 같은 어노테이션을 통해 MVC와 유사한 방식으로 메시지를 처리할 수 있고, 파싱 기능도 제공하기 때문에 유지보수성과 확장성이 좋아진다고 판단하여 WebSocket 위에 STOMP를 적용했습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (238,3,76,'화면에 사용자 이름이나 ID를 보여주려면 토큰 정보를 열어봐야 하는데 httpOnly 쿠키에 넣으면 자바스크립트가 접근할 수 없어 사용이 불가능합니다. 그래서 헤더 방식을 사용했고 대신 XSS 위험을 줄이기 위해 유효기간을 짧게 설정했습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (239,3,75,'Wrapper 클래스는 기본형 데이터를 객체로 감싼 클래스이며, 컬렉션 사용, 제네릭 적용, null 표현 등을 위해 사용됩니다. 자바는 오토박싱과 언박싱을 통해 자동 변환을 지원합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (240,3,74,'final은 최종적인 상태를 설정하고 변경을 제한합니다. 변수, 메서드, 클래스에 사용하여 재할당, 오버라이딩, 상속을 금지하여 코드의 안정성과 불변성을 보장합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (241,3,73,'트랜잭션의 4대 특징으로 작업은 모두 성공하거나 모두 실패해야하며 db제약 조건을 위반하면 안되며 동시에 동작하는 두 트랜잭션은 독립적이어야하고 커밋된 데이터는 영구적으로 유지되어야한다는 것입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (242,3,72,'동기는 작업 완료까지 기다리는 방식이고, 비동기는 결과를 기다리지 않고 다음 작업을 수행하는 방식입니다. <br>
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (243,3,71,'DispatcherServlet은 Spring MVC의 프론트 컨트롤러로, 모든 HTTP 요청을 받아 HandlerMapping을 통해 적절한 컨트롤러를 찾고, HandlerAdapter를 통해 실행한 뒤 ViewResolver를 거쳐 응답을 반환합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (244,3,70,'Autowiring은 @Autowired 어노테이션이 붙은 지점에 스프링 컨테이너가 Bean을 생성한 뒤 타입을 기준으로 의존성을 자동 주입하는 과정이며, 동일 타입을 우선 비교하고 타입이 여러개이면 이름을 비교한 후 그래도 모호할 경우@Qualifier나 @Primary를 통해 명시적으로 지정할 수 있습니다. 그래도 여전히 모호하면 예외를 발생시킵니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (245,3,69,'DI는 객체의 의존성을 외부에서 주입하는 방식이며, 생성자 주입, 필드 주입, Setter 주입이 있습니다. 생성자 주입은 불변성을 보장하고 테스트가 용이하여 가장 권장됩니다. 필드 주입은 간편하지만 순환 참조가 발생할 수 있고 테스트가 어렵다는 단점이 있습니다. setter 주입은 선택적 의존이 가능하지만 객체 생성 후 주입이 이루어지기 때문에 불완전한 상태로 존재할 가능성이 있다는 단점이 있습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (246,3,68,'웹소켓(WebSocket) 외에도 실시간 통신을 위한 다양한 방식이 있으며, 대표적으로 SSE(Server-Sent Events), 롱 폴링(Long Polling), 웹트릭(WebRTC) 등이 있습니다. 서버에서 클라이언트로의 단방향 데이터 전송이 필요하면 SSE를, 대규모 데이터 방송이 필요하면 롱 폴링을, P2P 영상/음성 통신은 웹트릭을 주로 사용합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (247,3,67,'http는 요청-응답 구조라서 실시간으로 오는 메시지를 확인하려면 폴링을 해야합니다. 웹소켓은 한번 연결되면 양방향 통신이 가능하기 때문에 채팅처럼 실시간으로 서버에서 클라이언트로 푸시가 필요한 기능은 웹소켓이 더 적합하다고 판단했습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (248,3,66,'보안과 편의성을 위해서 나누어서 사용했습니다. 액세스 토큰은 유효기간을 길게 잡으면 탈취 시 위험하고, 짧게 잡으면 사용자가 계속 로그인을 해야해서 불편함을 느낄 수 있습니다. 그래서 액세스 토큰은 유효기간을 짧게 하여 보안을 챙기고 리프레시 토큰을 통해 자동으로 로그인이 유지되게 하여 사용자 경험을 높였습니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (249,3,12,'논리적인 IP 주소를 기반으로 실제 장치의 물리적인 MAC 주소를 찾아내어 연결해 주는 네트워크 프로토콜입니다');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (250,3,22,'Runtime Data Area :
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (251,3,21,'자바 가상 머신(JVM) 위에서 실행되는 자바 코드가 C, C++, 어셈블리 등 네이티브 언어로 작성된 애플리케이션 및 라이브러리와 상호작용(호출)할 수 있게 해주는 인터페이스 프레임워크입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (252,3,20,'DB(데이터베이스)에서 옵티마이저(Optimizer)는 사용자가 작성한 SQL 쿼리를 가장 빠르고 효율적으로 처리할 수 있도록 최적의 경로(실행 계획, Execution Plan)를 수립하는 핵심 엔진입니다. 테이블의 통계 정보를 바탕으로 어떤 인덱스를 쓸지, 어떤 순서로 데이터를 읽을지 결정하여 시스템 리소스(I/O, CPU, 메모리)를 최소화합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (253,3,23,'가비지 컬렉션(GC)은 JVM의 힙(Heap) 메모리에서 더 이상 참조되지 않는 객체(가비지)를 찾아 자동으로 해제하는 프로세스입니다. 힙은 효율적인 관리를 위해 크게 Young Generation(신규 객체)과 Old Generation(장수 객체)으로 나뉘며, GC는 Minor GC(Young)와 Major/Full GC(Old)로 나뉘어 동작합니다. Minor GC에서 살아남아 설정된 Age(나이) 임계치에 도달한 객체가 Young 영역에서 Old 영역으로 옮겨지는 ''승격(Promotion)'' 과정이 발생합니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (254,3,14,'코드에는 실행 명령어가, 데이터에는 전역·정적 변수가, 힙에는 동적 할당된 객체가 저장되며, 스택에는 지역 변수와 함수 호출 정보가, 레지스터에는 CPU의 현재 작업 상태와 연산 데이터가 저장됩니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (255,3,17,'두 개 이상의 프로세스나 스레드가 공유 자원에 동시에 접근하여 변경을 시도할 때, 접근 순서에 따라 결과가 예상치 못하게 달라지는 데이터 불일치 문제입니다.');
INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (256,3,18,'독립된 프로세스들이 데이터를 주고받으며 협력할 수 있도록 운영체제가 제공하는 통신 기법입니다. 메모리가 분리되어 있어 직접 공유가 불가능한 프로세스 간에 공유 메모리 또는 메시지 전달 방식을 통해 통신하며, 주요 방식으로는 파이프, 소켓, 세마포어 등이 있습니다.');
