INSERT INTO ANSWER (ID,USER_ID,QUESTION_ID,ANSWER) values (258,3,10,'DNS는 사람이 읽기 쉬운 도메인 이름을 컴퓨터가 사용하는 IP 주소로 변환해 주는 인터넷의 전화번호부 시스템입니다. 그 과정은 브라우저 캐시를 먼저 확인한 뒤, 정보가 없다면 루트 서버부터 단계별 네임 서버를 거치는 재귀적 탐색을 통해 최종 IP 주소를 찾아내어 접속하는 방식입니다.');
