CREATE TABLE USER_TABLE (
    id            NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username      VARCHAR2(50) NOT NULL UNIQUE,
    password_hash VARCHAR2(300) NOT NULL
);

CREATE TABLE CATEGORY (
    id            NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name          VARCHAR2(20 CHAR) NOT NULL
);

CREATE TABLE QUESTION (
    id            NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    question      VARCHAR2(300 CHAR) NOT NULL,
    add_date      DATE DEFAULT SYSDATE,
    category_id   NUMBER,
    tts_key       VARCHAR2(50 CHAR),
    
    CONSTRAINT fk_question_userid FOREIGN KEY (category_id) REFERENCES CATEGORY(id) ON DELETE SET NULL
);

CREATE TABLE ANSWER (
    id            NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id       NUMBER NOT NULL,
    question_id   NUMBER NOT NULL,
    answer        VARCHAR2(1000 CHAR),
    
    CONSTRAINT fk_answer_userid FOREIGN KEY (user_id) REFERENCES USER_TABLE(id) ON DELETE CASCADE,
    CONSTRAINT fk_answer_questionid FOREIGN KEY (question_id) REFERENCES QUESTION(id) ON DELETE CASCADE
);

